pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 amount) public {
        // wide admissible domain: any non-zero caller, any amount incl. large
        vm.assume(actor != address(0));

        address owner = c.smartfix_owner();

        // fund the victim contract so a successful self-destruct moves real value
        vm.deal(address(c), uint256(amount));
        // give the actor gas-money style balance so deltas are observable
        vm.deal(actor, 1 ether);

        uint256 actorBefore = actor.balance;
        uint256 cBefore = address(c).balance;

        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // Universal rule: a call either reverts, OR it succeeds only for the stored
        // owner AND credits exactly the caller (msg.sender) with c's entire prior
        // balance, emptying c, leaving the stored owner unchanged.
        assertTrue(
            !ok || (
                actor == owner &&
                address(c).balance == 0 &&
                cBefore > 0 &&
                actor.balance - actorBefore == cBefore &&
                c.smartfix_owner() == owner
            )
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: keep wide; any actor may attempt the call.
        amount = bound(amount, 0, type(uint96).max);

        // Fund c directly so a successful self-destruct moves real value.
        vm.deal(address(c), amount);

        // Track the pre-call state.
        uint256 cBalBefore = address(c).balance;
        address storedOwner = c.smartfix_owner();
        uint256 callerBalBefore = address(actor).balance;

        // Drive c through sudicideAnyone from an arbitrary (fuzzed) caller.
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        if (!ok) {
            // Non-owner callers must revert and leave c fully intact.
            assertTrue(
                actor != storedOwner && address(c).balance == cBalBefore,
                "non-owner must revert and not disturb c"
            );
        } else {
            // Successful call: caller is the stored owner, c is emptied,
            // and the CALLER (msg.sender) is the party credited the funds.
            assertTrue(
                actor == storedOwner
                && address(c).balance == 0
                && address(actor).balance == callerBalBefore + cBalBefore,
                "destroyed funds must be credited to the calling msg.sender"
            );
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // WIDE domain: any actor, any fundable amount — do NOT constrain actor to the owner,
        // the difference only shows when a caller that is not the credited party is involved.
        vm.assume(actor != address(0));
        vm.deal(address(c), amount);

        uint256 cBalBefore = address(c).balance;
        uint256 actorBalBefore = actor.balance;

        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // General rule: for ANY caller, the call either reverts (no effect), or the CALLER
        // is credited c's entire prior balance (recipient == msg.sender) and c is emptied.
        assertTrue(
            !ok || (actor.balance == actorBalBefore + cBalBefore && address(c).balance == 0),
            "successful suicide must pay its entire balance to the caller msg.sender"
        );
    }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function runTest(address caller) public {
    require(caller != c.smartfix_owner());
    bool reverted = false;
    c.sudicideAnyone();
    assert(!reverted);
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted == (address(this) != c.smartfix_owner()));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        c.sudicideAnyone();
        assert(!reverted || (c.smartfix_owner() == address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        // Read the stored owner (public getter) BEFORE the deciding call.
        address ownerBefore = c.smartfix_owner();
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        // General rule: the call reverts exactly when this caller is not the stored owner.
        // Holds on P; on M the tautological require lets a non-owner call succeed, breaking it.
        assert(reverted == (ownerBefore != address(this)));
    }
    receive() external payable {}
}
